-- Publicaciones de relleno (ofertas de trabajo genéricas) para que la app
-- no se vea vacía a las primeras usuarias. Ninguna corresponde a una
-- empleadora real -- todas quedan bajo UNA sola cuenta "empresa" placeholder
-- (legalId = 'DEMO_RELLENO'), sin verificar, para poder ubicarlas y
-- borrarlas en bloque más adelante con un solo DELETE sobre esa cuenta
-- (JobPosting.company tiene onDelete: Cascade, así que borrar la
-- CompanyProfile se lleva sus 270 vacantes con ella):
--
--   DELETE FROM company_profiles WHERE "legalId" = 'DEMO_RELLENO';
--   -- (o, si se prefiere no perder también la cuenta de usuario asociada:)
--   DELETE FROM job_postings WHERE "companyId" = (SELECT id FROM company_profiles WHERE "legalId" = 'DEMO_RELLENO');
--
-- 10 categorías reales de la app x 27 publicaciones cada una = 270 en total,
-- repartidas entre ciudades reales de Costa Rica. Generadas con
-- scripts/tmp-generate-demo-jobs.ts (probado localmente antes de convertir
-- a SQL -- mismo contenido exacto, no una copia hecha a mano).
CREATE EXTENSION IF NOT EXISTS pgcrypto;

DO $$
BEGIN
  IF NOT EXISTS (SELECT 1 FROM "company_profiles" WHERE "legalId" = 'DEMO_RELLENO') THEN
    VALUES (
      gen_random_uuid()::text,
      'publicaciones.ejemplo@eltico.cr',
      -- bcrypt de un valor aleatorio -- nadie inicia sesión con esta cuenta.
      '$2b$10$N7NuBVIkUFp69zNn3jiVjOvGaRcXDRd2EBBLJgok.7/6D1PddBb2u',
      'COMPANY',
      now()
    );

      "id", "userId", "commercialName", "legalId", "responsibleName",
      "contactEmail", "location", "activity", "isVerified", "updatedAt"
    )
    VALUES (
      gen_random_uuid()::text,
      (SELECT id FROM "users" WHERE email = 'publicaciones.ejemplo@eltico.cr'),
      'Publicaciones de ejemplo — El Tico Bretea',
      'DEMO_RELLENO',
      'Contenido de ejemplo',
      'publicaciones.ejemplo@eltico.cr',
      'Costa Rica',
      'Publicaciones de relleno generadas para que la app no se vea vacía a las primeras usuarias. Borrar esta cuenta elimina todas sus vacantes en bloque (onDelete: Cascade).',
      false,
      now()
    );
  END IF;
END $$;

